import{_ as e,o as t,c as a}from"./chunks/framework.9yf7n3zg.js";const u=JSON.parse(`{"title":"Leathercase guide: story structure over your own files","titleTemplate":false,"description":"","frontmatter":{"layout":"home","title":"Leathercase guide: story structure over your own files","titleTemplate":false,"hero":{"name":"Leathercase","text":"A desk for your story, over the files you already have.","tagline":"Keep writing where you write, or write in Leathercase. It reads your manuscript, whether it is a folder of Markdown notes, a Word file, a Scrivener project or a Fountain screenplay, and draws the story from it. No agent or model ever writes your prose.","image":{"src":"/favicon.svg","alt":"Leathercase"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"A tour of the window","link":"/guide/tour"},{"theme":"alt","text":"Download","link":"https://github.com/Leathercase/leathercase-releases/releases/latest"}]},"features":[{"title":"Your files are read, never written","details":"Leathercase opens the folder you already keep and reads it. What it adds, such as threads, comments and cards, goes into small Markdown and JSON files in a folder of its own, readable without it.","link":"/reference/suite-files"},{"title":"Plot grid","details":"Every scene down the side, your threads across the top, and in each cell what the thread does in that scene. A gauge draws where the story turns.","link":"/guide/plot-grid"},{"title":"Threads","details":"The manuscript as one line, and every promise, motif and subplot as a lane over it, with the echoes heard offline.","link":"/guide/threads"},{"title":"Graph","details":"Every name in the story and the ties you draw between them, read with graph theory in plain words, in tabs you make from templates such as Truby's character web.","link":"/guide/graph"},{"title":"Manuscript","details":"The whole story on one page, with lenses for rhythm, style, dialogue and accents, comments in the margin, and a click back to the file in your own app.","link":"/guide/manuscript"},{"title":"Beat board","details":"The beats of a structure you choose, with cards under each, and a card that becomes a planned scene on the grid.","link":"/guide/beat-board"},{"title":"Characters","details":"A sheet for each person in the story, from their voice to their origin, built from what the story already says about them.","link":"/guide/characters"},{"title":"The Writer Board","details":"The level above every story, where the themes, ideas, voices and research you keep returning to live as cards.","link":"/guide/writer-board"},{"title":"Offline first, models on command","details":"Everything above runs on your computer with no account and no network. The mate, Leathercase's own assistant, reads with Leathercase's rules and wakes no model. An outside agent reaches your stories only when you connect it, and only through Leathercase's rules.","link":"/guide/mate"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1792685126000}`),r={name:"index.md"};function s(o,i,n,d,l,h){return t(),a("div")}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
